export const getDoctorDistributionUrl = (id: string,
    params?: DoctorDistributionParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/distributions/${id}/doctor?${stringifiedParams}` : `/distributions/${id}/doctor`
}

export const doctorDistribution = async (id: string,
    params?: DoctorDistributionParams, options?: RequestInit): Promise<doctorDistributionResponse> => {
  
  return customInstance<doctorDistributionResponse>(getDoctorDistributionUrl(id,params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





